package run.ikaros.sharing; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.security.NoSuchAlgorithmException; import java.time.Instant; import java.util.Base64; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException;
@Service public class PersistentShareService implements ShareService{private final ShareRepository repository;public PersistentShareService(ShareRepository r){repository=r;}@Override public Mono<ShareView> create(UUID issuer,CreateShareRequest r){if(r.expiresAt()!=null&&!r.expiresAt().isAfter(Instant.now()))return Mono.error(new IllegalArgumentException("Share 过期时间必须在未来"));if(r.granteeType()==ShareGranteeType.USER&&r.granteeId()==null)return Mono.error(new IllegalArgumentException("用户分享必须指定 granteeId"));String token=r.granteeType()==ShareGranteeType.LINK_TOKEN?UUID.randomUUID().toString():null;Instant now=Instant.now();return repository.save(new ShareEntity(null,issuer,r.targetType(),r.targetId(),r.granteeType(),r.granteeId(),r.capabilities(),token==null?null:digest(token),r.expiresAt(),ShareStatus.ACTIVE,now,now,null)).map(s->withToken(view(s),token));}@Override public Flux<ShareView> list(UUID issuer){return repository.findAllByIssuerIdOrderByCreatedAtDesc(issuer).map(this::view);}@Override public Mono<ShareView> revoke(UUID issuer,UUID id){return repository.findById(id).filter(s->s.issuerId().equals(issuer)).switchIfEmpty(Mono.error(new NotFoundException("Share 不存在或无权操作"))).flatMap(s->repository.save(new ShareEntity(s.id(),s.issuerId(),s.targetType(),s.targetId(),s.granteeType(),s.granteeId(),s.capabilities(),s.tokenDigest(),s.expiresAt(),ShareStatus.REVOKED,s.createdAt(),Instant.now(),s.version()))).map(this::view);}@Override public Mono<ShareView> redeem(String token){if(token==null||token.isBlank())return Mono.error(new IllegalArgumentException("Share Token 不能为空"));return repository.findByTokenDigest(digest(token)).switchIfEmpty(Mono.error(new NotFoundException("Share Token 无效"))).flatMap(s->{if(s.status()!=ShareStatus.ACTIVE)return Mono.error(new NotFoundException("Share 已撤销"));if(s.expiresAt()!=null&&!s.expiresAt().isAfter(Instant.now()))return Mono.error(new NotFoundException("Share 已过期"));return Mono.just(view(s));});}private String digest(String token){try{return Base64.getUrlEncoder().withoutPadding().encodeToString(MessageDigest.getInstance("SHA-256").digest(token.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}private ShareView view(ShareEntity s){return new ShareView(s.id(),s.issuerId(),s.targetType(),s.targetId(),s.granteeType(),s.granteeId(),s.capabilities(),s.expiresAt(),s.status(),s.createdAt(),null);}private ShareView withToken(ShareView s,String token){return new ShareView(s.id(),s.issuerId(),s.targetType(),s.targetId(),s.granteeType(),s.granteeId(),s.capabilities(),s.expiresAt(),s.status(),s.createdAt(),token);}}
